import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
    except StopIteration:
        return

    parents = []
    counts = []

    for i in range(n):
        p = int(next(iterator))
        c = int(next(iterator))
        parents.append(p)
        counts.append(c)

    adj = [[] for _ in range(n + 1)]
    root = 0

    for i in range(1, n + 1):
        p = parents[i - 1]
        if p == 0:
            root = i
        else:
            adj[p].append(i)

    order = []
    stack = [root]
    while stack:
        u = stack.pop()
        order.append(u)
        for v in adj[u]:
            stack.append(v)

    order.reverse()

    subtree_size = [0] * (n + 1)
    for u in order:
        s = 1
        for v in adj[u]:
            s += subtree_size[v]
        subtree_size[u] = s

    for i in range(1, n + 1):
            c = counts[i - 1]
            sz = subtree_size[i]
            if c >= sz:
                print("NO")
                return

    values = {}
    used = [False] * (n + 1)

    for u in order:
        c = counts[u - 1]
        current_count = 0
        target = c + 1

        k = 0
        for x in range(1, n + 1):
            if not used[x]:
                current_count += 1
                if current_count == target:
                    values[u] = x
                    used[x] = True
                    break

    result = []
    for i in range(1, n + 1):
        result.append(str(values[i]))

    print("YES")
    print(" ".join(result))

if __name__ == "__main__":
    solve()
